# go-fuck shim for PowerShell, modeled after thefuck's scripts/fuck.ps1.
#
# Put this script somewhere on PATH and call "fuck" from PowerShell. The first
# call adds the go-fuck initialization to the user profile and defines the
# fuck() function for the current session; later calls delegate to it.
#
# The function itself is generated by "go-fuck --alias"; see README.md for the
# supported shells and the TF_SHELL/TF_ALIAS mechanism.

if (-not (Get-Command "go-fuck" -ErrorAction Ignore)) {
    Write-Error "go-fuck is not on PATH. Install it with: go install github.com/leafevans/go-fuck/cmd/go-fuck@latest"
    exit 1
}

# If the function was already initialized, hand the call over to it.
if ((Get-Command "fuck" -ErrorAction Ignore).CommandType -eq "Function") {
    fuck @args
    [Console]::ResetColor()
    exit
}

"First time use of go-fuck detected."

$profileContent = Get-Content $PROFILE -Raw -ErrorAction Ignore
if ($profileContent -like "*go-fuck*") {
    "  - go-fuck initialization already present in $PROFILE"
} else {
    "  - Adding go-fuck initialization to $PROFILE"
    $snippet = @'

# go-fuck shell integration
if (Get-Command go-fuck -ErrorAction Ignore) {
    iex "$(go-fuck --alias)"
}
'@
    Add-Content -Path $PROFILE -Value $snippet
}

"  - Adding fuck() function to the current session..."
$alias = go-fuck --alias
if ($LASTEXITCODE -ne 0) {
    Write-Error "go-fuck --alias failed with exit code $LASTEXITCODE"
    exit 1
}
# Define the function in the global scope so that it survives this script.
$alias = $alias.Replace("function fuck", "function global:fuck")
Invoke-Expression $alias

"  - Invoking fuck()"
fuck @args
[Console]::ResetColor()
